
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_mn12_sx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_mn12_sx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.837553671907407e-01, -2.770456660953077e-01, -2.672311716538323e-01, -2.527624751034688e-01, -2.312711060544730e-01, -1.994278522059517e-01, -1.537830806770867e-01, -9.120434604030983e-02, 8.076440255445306e-03, 1.348704865594876e-01, 5.629477776771227e-02, -1.357889765661192e-01, -3.487429074162916e-02, -2.799045210023801e-02, 2.282134840118324e-02, 7.251847922778579e-03, -2.008104578650949e-01, -1.580541194594825e-01, -4.729137687655407e-02, -6.757521044845166e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


